'use strict';

// MAIN //

class Float16Array {
	constructor(length) {
		if (typeof length === 'number') {
			this._buffer = new Uint16Array(length);
		} else if (Array.isArray(length)) {
			this._buffer = new Uint16Array(length.length);
			for (let i = 0; i < length.length; i++) {
				this._buffer[i] = Float16Array.toFloat16(length[i]);
			}
		} else {
			throw new TypeError('Unsupported constructor argument');
		}
		this.length = this._buffer.length;
	}

	get(index) {
		return Float16Array.fromFloat16(this._buffer[index]);
	}

	set(index, value) {
		this._buffer[index] = Float16Array.toFloat16(value);
	}

	static toFloat16(val) {
		// Simple approximation (not IEEE-754 accurate)
		const f32 = new Float32Array(1);
		f32[0] = val;
		const u32 = new Uint32Array(f32.buffer);
		return u32[0] >>> 16;
	}

	static fromFloat16(bits) {
		const u32 = new Uint32Array(1);
		u32[0] = bits << 16;
		const f32 = new Float32Array(u32.buffer);
		return f32[0];
	}
}


// EXPORTS //

module.exports = Float16Array;
